"use client";

import { getImageProps, type StaticImageData } from "next/image";
import { useMemo } from "react";
import Lightbox, {
  type ImageSource,
  type SlideImage,
} from "yet-another-react-lightbox";
import Captions from "yet-another-react-lightbox/plugins/captions";
import Zoom from "yet-another-react-lightbox/plugins/zoom";
import "yet-another-react-lightbox/plugins/captions.css";
import "yet-another-react-lightbox/styles.css";
import type { Photo } from "@/data/site";

/**
 * Turns the `srcset` generated by next/image into lightbox sources so slides get
 * optimized AVIF/WebP instead of the original file. Widths past the original are
 * capped (the optimizer never upscales), so the list stops at the original size.
 * Undefined when optimization is off (dev), and the lightbox falls back to `src`.
 */
function toSources(
  srcSet: string | undefined,
  { width, height }: StaticImageData,
): ImageSource[] | undefined {
  if (!srcSet) return undefined;
  const sources: ImageSource[] = [];
  for (const entry of srcSet.split(", ")) {
    const [src, descriptor] = entry.split(" ");
    const w = Math.min(Number.parseInt(descriptor, 10), width);
    sources.push({ src, width: w, height: Math.round((height * w) / width) });
    if (w === width) break;
  }
  return sources;
}

function toSlide({ image, alt, caption }: Photo): SlideImage {
  const { props } = getImageProps({ src: image, alt, sizes: "100vw" });
  return {
    src: props.src,
    alt,
    width: image.width,
    height: image.height,
    srcSet: toSources(props.srcSet, image),
    ...(caption ? { description: caption } : {}),
  };
}

type PhotographyLightboxProps = {
  photos: readonly Photo[];
  open: boolean;
  index: number;
  onClose: () => void;
  onView: (index: number) => void;
};

export function PhotographyLightbox({
  photos,
  open,
  index,
  onClose,
  onView,
}: PhotographyLightboxProps) {
  const slides = useMemo(() => photos.map(toSlide), [photos]);

  return (
    <Lightbox
      open={open}
      close={onClose}
      index={index}
      slides={slides}
      plugins={[Captions, Zoom]}
      carousel={{ finite: true, padding: "16px", spacing: "12px" }}
      animation={{ fade: 280 }}
      captions={{
        showToggle: true,
        descriptionTextAlign: "center",
      }}
      controller={{ closeOnBackdropClick: true }}
      on={{ view: ({ index: next }) => onView(next) }}
      zoom={{ maxZoomPixelRatio: 3, scrollToZoom: true }}
    />
  );
}
